using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

var source = Path.GetFullPath(args[0]);
var root = Path.GetFullPath(args[1]); Directory.CreateDirectory(Path.Combine(root,"data"));
foreach (var file in new[]{"rfq-intakes.json","rfq-lanes.json"}) File.Copy(Path.Combine(source,"data",file),Path.Combine(root,"data",file),true);
