void Check(bool ok,string message) { if(!ok)throw new Exception(message);count++;Console.WriteLine("PASS: "+message); }
async Task Reject(Func<Task> action,string code) { try{await action();}catch(SimRfqIntakeProblem p){Check(p.Code==code,$"reject {code}");return;}throw new Exception("Expected "+code); }
var original = File.ReadAllText(Path.Combine(root,"data","rfq-intakes.json"));
