Check((await new SimRfqIntakeStore(root).ReadAsync("RFQI-SIM-0043")) is SimRfqIntakeRecord { OrderIntake.ReviewStatus: "DRAFT" }, "fresh store instance reads durable draft by intake ID");
Check(File.ReadAllText(Path.Combine(root,"data","rfq-intakes.json"))==original,"draft discovery and retrieval are read-only");
