foreach(var doc in existingPo.OrderIntake!.PoEvidence) foreach(var suffix in new[]{".bin",".json"})
    File.Copy(Path.Combine(source,evidenceFolder,doc.Document.DocumentId+suffix),Path.Combine(root,evidenceFolder,doc.Document.DocumentId+suffix),true);
var extraction=await store.ExtractOrderPo(new(existingPo.RequestCorrelationId,existingPo.IntakeId,existingPo.OrderIntake.PoEvidence.Select(e=>e.Document).ToArray()),persona);
