Check(extraction.Fields["quoteReference"].Value=="SIM-Q-0042-R01" && extraction.Fields["customer"].Value=="DLE-SIM-CUSTOMER" && extraction.Fields.Values.All(f=>f.Page==1 && f.Sha256?.Length==64 && f.DocumentId is not null),"PO suggestions retain document hash, page, excerpt and identity evidence");
Check(extraction.Fields["payment"].Value.Contains("Net 30") && extraction.Fields["requirements"].Value.Contains("SIM001-A-010"),"commercial and shipment requirements retained as PO evidence text");
Check(File.ReadAllText(Path.Combine(root,"data","rfq-intakes.json"))==original,"PO extraction does not write draft history or facts");
var matches = await store.SearchOrderQuotes("SIM-CUSTOMER-E2E-001","SIM-ASSY-001 A","SUBMITTED");
var quote = matches.Single(q=>q.Reference.QuoteNumber=="SIM-Q-0042-R01");
Check(quote.Reference.IntakeId=="RFQI-SIM-0042"&&quote.Reference.ApprovalVersion==1,"discover exact submitted approval by assembly/revision");
Check((await store.SearchOrderQuotes(null,"DLE-SIM-CUSTOMER","SUBMITTED")).Any(q=>q.Reference==quote.Reference),"customer search");
Check((await store.SearchOrderQuotes(null,"SIM-Q-0042-R01","SUBMITTED")).Single().Reference==quote.Reference,"quote number search");
Check(quote.Approval.Summary.CombinedUnitPrice==70.64m&&quote.Approval.Summary.Total==706.40m&&quote.Approval.Answers.Delivery=="3 Weeks","frozen price and lead baseline");
Check(!(await store.SearchOrderQuotes(quote.Customer.CustomerId,"SIM-Q-0042","HISTORY")).Any(),"submitted is not duplicated into History");
var facts = new SimOrderFacts("2026-09-22",[new("SIM-ASSY-001","A",10,"USD",70.64m,706.40m)],"Customer requests three weeks after acceptance",0,0);
