var extractedComparison=await store.PreviewOrder(new(quote.Customer,extraction.Facts,true,quote.Reference));
Check(extractedComparison.Comparison.Take(11).All(c=>c.Result=="MATCH") && extractedComparison.Comparison.Where(c=>c.Field is "Delivery" or "Payment terms" or "Shipping terms").All(c=>c.Result=="NOT_COMPARABLE"),"independent PO-vs-quote core matches while terms remain reviewable");
Check(preview.TechnicalBaseline?.Quote == quote.Reference && preview.TechnicalBaseline.Definition.Materials.Candidate.Rows.Length == 12,"exact approval resolves accepted 12-row definition and labor snapshot");
Check(preview.TechnicalBaseline!.Labor.Operations.Any(o => (o.Visuals?.Length ?? 0) > 0),"quoted labor visual references retained");
Check(preview.Comparison.Take(11).All(c=>c.Result=="MATCH"),"all core facts, charges, total and arithmetic match");
Check(preview.Comparison.Where(c=>c.Field is "Delivery" or "Payment terms" or "Shipping terms" or "Scope").All(c=>c.Result=="NOT_COMPARABLE"),"unmodeled terms and calendar delivery never invented as matching");
