Check((await store.PreviewOrder(new(quote.Customer,facts with{Nre=null},true,quote.Reference))).Comparison.Single(c=>c.Field=="NRE").Result=="MISSING","missing charges not assumed zero");
Check((await store.PreviewOrder(new(quote.Customer,facts,false,null))).Comparison.Where(c=>c.Field!="Line arithmetic").All(c=>c.Result=="NOT_APPLICABLE"),"no quote comparison N/A");
