Check((await new SimRfqIntakeStore(root).FindOrders(quote.Customer.CustomerId," test-only-po ",null)).Single().IntakeId==saved.Record.IntakeId,"restart/resume by normalized customer PO");
Check((await store.FindOrders(quote.Customer.CustomerId,null,quote.Reference.ApprovalId)).Any(r=>r.IntakeId==saved.Record.IntakeId),"future quote door finds existing draft");
var afterSave = File.ReadAllText(Path.Combine(root,"data","rfq-intakes.json"));
