Check(duplicate.Resumed&&duplicate.Record.IntakeId==saved.Record.IntakeId,"second door/repeated PO returns same intake");
await Reject(()=>store.SaveOrder(request with{RequestId=Guid.NewGuid().ToString(),IntakeId=saved.Record.IntakeId},persona,metadata),"ORDER_STALE");
var second = await store.SaveOrder(request with{RequestId=Guid.NewGuid().ToString(),CorrelationId=Guid.NewGuid().ToString(),PoNumber="TEST-ONLY-SECOND-PO"},persona,metadata);
Check(second.Record.IntakeId!=saved.Record.IntakeId,"different PO may reuse quote");
var raceRequest=request with{RequestId=Guid.NewGuid().ToString(),CorrelationId=Guid.NewGuid().ToString(),PoNumber="TEST-ONLY-RACE"};
var race=await Task.WhenAll(store.SaveOrder(raceRequest,persona,metadata),store.SaveOrder(raceRequest with{RequestId=Guid.NewGuid().ToString(),CorrelationId=Guid.NewGuid().ToString()},persona,metadata));
Check(race[0].Record.IntakeId==race[1].Record.IntakeId,"simultaneous doors create one canonical intake");
var evidence = await store.StageDocument(request.CorrelationId,"isolated-order-evidence.txt",0,new MemoryStream(Encoding.UTF8.GetBytes("Isolated automated test evidence; not an E2E customer PO.")),persona);
var questionnaire = new SimContractReviewRequest(request.PoNumber,"CUSTOMER_PO",true,null,true,null,"WILL_CALL",null,"NEW_ASSEMBLY",true,null,null,null,false,[],[],"None","","",true);
var submit = request with{RequestId=Guid.NewGuid().ToString(),IntakeId=saved.Record.IntakeId,ExpectedRevision=1,Documents=[evidence],Questionnaire=questionnaire,Submit=true,PoFactsConfirmed=true,PoDateVerified=true,DueDateDecision=new("CLARIFICATION","Customer must specify arrival date"),TechnicalSourceChoice="QUOTED_DEFINITION"};
await Reject(()=>store.SaveOrder(submit with{PoFactsConfirmed=false},persona,metadata),"ORDER_PO_CONFIRM");
await Reject(()=>store.SaveOrder(submit with{TechnicalSourceChoice=null},persona,metadata),"ORDER_TECHNICAL_SOURCE");
await Reject(()=>store.SaveOrder(submit with{Documents=[]},persona,metadata),"ORDER_EVIDENCE");
await Reject(()=>store.SaveOrder(submit with{Questionnaire=questionnaire with{RequirementsIdentifiedOnAttachedDocument=false}},persona,metadata),"ORDER_EVIDENCE");
var submitted = (await store.SaveOrder(submit,persona,metadata)).Record;
Check(submitted.OrderIntake!.TechnicalSource!.Status=="QUOTED_DEFINITION_LINKED" && submitted.OrderIntake.TechnicalSource.Documents.Length==0,"quoted definition reused without duplicate upload or technical re-review");
Check(submitted.Status=="READY_FOR_CONTRACT_REVIEW"&&submitted.TechnicalReview is null&&submitted.ContractReview is null,"submission is not technical review or contract acceptance");
Check(!JsonSerializer.Serialize(await store.ListOrderDrafts(),json).Contains(submitted.IntakeId),"submitted packages excluded from resume list");
Check(submitted.TechnicalFiles.Length==0&&submitted.OrderIntake!.PoEvidence.Single().Type=="CUSTOMER_PO"&&submitted.OrderIntake.PoEvidence.Single().Sha256.Length==64,"verified hashed PO is Intake-owned, outside technical package");
Check((await store.OpenDocument(submitted.IntakeId,evidence.DocumentId!)).Bytes.Length==evidence.Size,"PO retrieval uses existing binary storage");
var changedEvidence=await store.StageDocument(second.Record.RequestCorrelationId,"order-po.txt",0,new MemoryStream(Encoding.UTF8.GetBytes("Isolated second PO.")),persona);
var changedTechnical=await store.StageDocument(second.Record.RequestCorrelationId,"revision-b.txt",0,new MemoryStream(Encoding.UTF8.GetBytes("Incoming revision B for manual delta review.")),persona);
var revisedRequest=submit with{RequestId=Guid.NewGuid().ToString(),CorrelationId=second.Record.RequestCorrelationId,IntakeId=second.Record.IntakeId,PoNumber="TEST-ONLY-SECOND-PO",Documents=[changedEvidence],IncomingTechnicalDocuments=[changedTechnical],TechnicalSourceChoice="NEW_DOCUMENTS",Facts=changed};
var revised=(await store.SaveOrder(revisedRequest,persona,metadata)).Record;
Check(revised.OrderIntake!.TechnicalSource!.Status=="TECHNICAL_REVIEW_REQUIRED" && revised.OrderIntake.TechnicalSource.Baseline!.Quote==quote.Reference && revised.OrderIntake.TechnicalSource.ReviewReasons.Any(r=>r.StartsWith("Revision:")),"new documents retain exact quoted baseline and identify revision difference for scoped review");
Check(revised.TechnicalReview is null && revised.TechnicalFiles.Length==0,"incoming files do not overwrite accepted technical package or auto-start broad Technical Review");
Check(!JsonSerializer.Serialize(await store.ListTechnicalReviewsAsync(),json).Contains(submitted.IntakeId),"submitted order excluded from Technical Review queue");
Check(submitted.OrderIntake!.Questionnaire!.PriceMatchesQuote is null&&submitted.OrderIntake.History.Length==2&&submitted.OrderIntake.History.All(h=>h.ActorId==persona.Id),"manual price answer absent; append-only actor audit");
await Reject(()=>store.SaveOrder(submit with{RequestId=Guid.NewGuid().ToString(),ExpectedRevision=2},persona,metadata),"ORDER_STALE");
var noQuoteRequest=request with{RequestId=Guid.NewGuid().ToString(),CorrelationId=Guid.NewGuid().ToString(),PoNumber="TEST-ONLY-UNQUOTED",Quote=null,PreviouslyQuoted=false};
var unquoted=await store.SaveOrder(noQuoteRequest,persona,metadata);
var noQuoteDoc=await store.StageDocument(noQuoteRequest.CorrelationId,"test-evidence.txt",0,new MemoryStream(Encoding.UTF8.GetBytes("Isolated no-quote test evidence.")),persona);
var noQuoteSubmit=noQuoteRequest with{RequestId=Guid.NewGuid().ToString(),IntakeId=unquoted.Record.IntakeId,ExpectedRevision=1,Documents=[noQuoteDoc],Questionnaire=questionnaire,Submit=true,PoFactsConfirmed=true,PoDateVerified=true,DueDateDecision=new("CLARIFICATION","Customer must specify arrival date")};
await Reject(()=>store.SaveOrder(noQuoteSubmit with{TechnicalSourceChoice="QUOTED_DEFINITION"},persona,metadata),"ORDER_TECHNICAL_SOURCE");
await Reject(()=>store.SaveOrder(noQuoteSubmit with{TechnicalSourceChoice="NEW_DOCUMENTS"},persona,metadata),"ORDER_TECHNICAL_SOURCE");
await Reject(()=>store.SaveOrder(noQuoteSubmit with{TechnicalSourceChoice="NEW_DOCUMENTS",IncomingTechnicalDocuments=[noQuoteDoc]},persona,metadata),"ORDER_TECHNICAL_EVIDENCE");
var technicalDoc=await store.StageDocument(noQuoteRequest.CorrelationId,"incoming-technical.txt",0,new MemoryStream(Encoding.UTF8.GetBytes("Isolated incoming technical evidence.")),persona);
var noQuoteSubmitted=await store.SaveOrder(noQuoteSubmit with{TechnicalSourceChoice="NEW_DOCUMENTS",IncomingTechnicalDocuments=[technicalDoc]},persona,metadata);
Check(noQuoteSubmitted.Record.OrderIntake!.TechnicalSource!.Status=="TECHNICAL_REVIEW_REQUIRED" && noQuoteSubmitted.Record.OrderIntake.TechnicalSource.Baseline is null,"unquoted incoming evidence requires scoped technical triage, never build-ready");
Check((await store.OpenDocument(noQuoteSubmitted.Record.IntakeId,technicalDoc.DocumentId!)).Bytes.Length==technicalDoc.Size,"incoming technical evidence retrieved from existing verified storage");
Check(noQuoteSubmitted.Record.Status=="READY_FOR_CONTRACT_REVIEW"&&noQuoteSubmitted.Record.OrderIntake!.Quote is null,"no-quote manual path submits for distinct review");
await Reject(()=>store.SaveOrder(noQuoteRequest with{RequestId=Guid.NewGuid().ToString(),IntakeId=unquoted.Record.IntakeId,ExpectedRevision=2,Submit=true,PoFactsConfirmed=true,PoDateVerified=true,DueDateDecision=new("CLARIFICATION","Customer must specify arrival date"),Facts=facts with{PoDate=null}},persona,metadata),"ORDER_FACTS");
await Reject(()=>store.CreateAsync(new("NEW_ORDER",quote.Customer,0,[],"",true,[],[],null,Guid.NewGuid().ToString(),questionnaire),persona,metadata),"ORDER_CANONICAL_FLOW");
var oldRecords=JsonNode.Parse(original)!["records"]!.AsArray();var newRecords=JsonNode.Parse(File.ReadAllText(Path.Combine(root,"data","rfq-intakes.json")))!["records"]!.AsArray();
Check(oldRecords.All(r=>JsonNode.DeepEquals(r,newRecords.Single(n=>n!["intakeId"]!.ToString()==r!["intakeId"]!.ToString()))),"every pre-existing intake/BOM/technical record preserved");
Check(File.ReadAllText(Path.Combine(root,"data","rfq-lanes.json"))==lanes,"source pricing, labor, approval and submitted lifecycle byte-preserved");
var reviewCorrelation=Guid.NewGuid().ToString();
var reviewDoc=await store.StageDocument(reviewCorrelation,"customer-po.pdf",0,new MemoryStream((await store.OpenDocument(existingPo.IntakeId,existingPo.OrderIntake.PoEvidence[0].Document.DocumentId!)).Bytes),persona);
var factReviewRequest=request with {RequestId=Guid.NewGuid().ToString(),CorrelationId=reviewCorrelation,PoNumber="ISOLATED-FACT-REVIEW",Facts=extraction.Facts with{PoDate="2026-09-22"},Documents=[reviewDoc],PoFactsConfirmed=true,FlowVersion=2,WizardStepKey="order-comparison"};
var factReview=(await store.SaveOrder(factReviewRequest,persona,metadata)).Record;
Check(factReview.OrderIntake!.PoFactReviews!.Single().Extraction.Fields["quantity"].Value=="10" && factReview.OrderIntake!.PoFactReviews![0].ReviewerId==persona.Id,"confirmation persists server-derived evidence and reviewer audit");
var corrected=factReviewRequest with { RequestId=Guid.NewGuid().ToString(),IntakeId=factReview.IntakeId,ExpectedRevision=1,Facts=extraction.Facts with{PoDate="2026-09-22",Lines=[extraction.Facts.Lines[0] with{Quantity=11}]} };
var correction=(await store.SaveOrder(corrected,persona,metadata)).Record;
Check(correction.OrderIntake!.PoFactReviews!.Length==2 && correction.OrderIntake.PoFactReviews[1].Corrections.Contains("quantity") && correction.OrderIntake.PoFactReviews[0].ConfirmedFacts.Lines[0].Quantity==10,"corrected facts append history without overwriting prior confirmation or extraction");
// Manual contractual dates: isolated fixtures only.
var dateRequest=request with {RequestId=Guid.NewGuid().ToString(),CorrelationId=Guid.NewGuid().ToString(),PoNumber="ISOLATED-MANUAL-DATES",PoDateVerified=true,
    Facts=facts with{Lines=[facts.Lines[0] with{CustomerDueDate="2026-10-14"}]},DueDateDecision=new("ACCEPT",null)};
var dateDraft=(await store.SaveOrder(dateRequest,persona,metadata)).Record;
var dates=dateDraft.OrderIntake!.ContractDates!;
Check(dates.PoDateVerification!.Date=="2026-09-22" && dates.DueDateReview is {Date:"2026-10-14",Disposition:"ACCEPT"} && dates.History.All(e=>e.ReviewerId==persona.Id),"manual PO verification and due-date acceptance receive server actor/time audit");
var dateResume=(SimRfqIntakeRecord)(await new SimRfqIntakeStore(root).ReadAsync(dateDraft.IntakeId))!;
