var dateEdit=dateRequest with{RequestId=Guid.NewGuid().ToString(),IntakeId=dateDraft.IntakeId,ExpectedRevision=1,Facts=dateRequest.Facts with{Lines=[dateRequest.Facts.Lines[0] with{CustomerDueDate="2026-10-15"}]},DueDateDecision=null,DueDateNote="Unfinished note"};
var changedDate=(await store.SaveOrder(dateEdit,persona,metadata)).Record;
