await Reject(()=>store.SaveOrder(baseDate with{Facts=dateRequest.Facts,DueDateDecision=new("CANNOT_MEET","")},persona,metadata),"ORDER_DUE_NOTE");
await Reject(()=>store.SaveOrder(baseDate with{Facts=facts with{Lines=[facts.Lines[0] with{CustomerDueDate="2026-02-30"}]}},persona,metadata),"ORDER_DUE_DATE");
