await Reject(()=>store.SaveOrder(baseDate with{Submit=true,DueDateDecision=null},persona,metadata),"ORDER_DUE_REVIEW");
var clarification=(await store.SaveOrder(baseDate with{DueDateDecision=new("CLARIFICATION","Await customer date")},persona,metadata)).Record;
Check(clarification.OrderIntake!.ContractDates!.DueDateReview is {Date:null,Disposition:"CLARIFICATION"},"clarification can retain an unknown due date without acceptance");
var cannot=(await store.SaveOrder(baseDate with{RequestId=Guid.NewGuid().ToString(),CorrelationId=Guid.NewGuid().ToString(),PoNumber="ISOLATED-CANNOT",Facts=dateRequest.Facts,DueDateDecision=new("CANNOT_MEET","Discuss later delivery")},persona,metadata)).Record;
